// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

args.new_string:
// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise each period that has started by now is renewed in order, and each one is
// invoiced: a licensed plan bills the new period in advance, a metered plan bills the usage of the period that ended. Periods
// follow the subscription's anchor (see anchor), so when the job runs late it catches up on every missed period, each with
// its own invoice. A declined charge makes the subscription past due. RenewDue returns how many subscriptions it renewed or
// canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		changed, err := s.renew(ctx, sub, now)
		if err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		if changed {
			n++
		}
	}
	return n, nil
}

// anchor is the start of a subscription's first paid period: its trial end for one that started with a trial, else its start.
func anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return *sub.TrialEnd
	}
	return sub.StartedAt
}

// renew renews a subscription whose period has ended, once for each period that has started by now. It reports whether it
// renewed or canceled the subscription. Each renewed period is saved as it is invoiced, so an error leaves the periods
// before it renewed and the rest for the next run.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err == nil, err
	}
	at := anchor(sub)
	// prevStart and prevEnd are the period that ended most recently: the one a metered plan bills.
	prevStart, prevEnd := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	declined := false
	renewed := false
	for n := billing.PeriodIndex(at, plan.Interval, sub.CurrentPeriodEnd); ; n++ {
		start := billing.PeriodStart(at, plan.Interval, n)
		if start.After(now) {
			break
		}
		end := billing.PeriodStart(at, plan.Interval, n+1)
		paid := true
		var err error
		switch {
		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
			paid, err = s.invoicePeriod(ctx, sub, plan, prevStart, prevEnd)
		case plan.UsageType == store.Licensed:
			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
		}
		if err != nil {
			return renewed, err
		}
		declined = declined || !paid
		status := store.Active
		if declined {
			status = store.PastDue
		}
		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.CurrentPeriodStart, x.CurrentPeriodEnd, x.Status = start, end, status
			return nil
		})
		if err != nil {
			return renewed, err
		}
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
		prevStart, prevEnd = start, end
		renewed = true
	}
	return renewed, nil
}

