func TestPeriodStartKeepsTheAnchorDay(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 23, 59, 59, 0, time.UTC)
	want := []time.Time{
		time.Date(2026, 1, 31, 23, 59, 59, 0, time.UTC),
		time.Date(2026, 2, 28, 23, 59, 59, 0, time.UTC),
		time.Date(2026, 3, 31, 23, 59, 59, 0, time.UTC),
		time.Date(2026, 4, 30, 23, 59, 59, 0, time.UTC),
		time.Date(2026, 5, 31, 23, 59, 59, 0, time.UTC),
	}
	for n, w := range want {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("period %d = %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartYearlyFromLeapDay(t *testing.T) {
	anchor := time.Date(2024, 2, 29, 0, 0, 0, 0, time.UTC)
	for n, w := range map[int]time.Time{
		1: time.Date(2025, 2, 28, 0, 0, 0, 0, time.UTC),
		2: time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC),
		3: time.Date(2027, 2, 28, 0, 0, 0, 0, time.UTC),
		4: time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC),
	} {
		if got := PeriodStart(anchor, store.Yearly, n); !got.Equal(w) {
			t.Errorf("period %d = %v, want %v", n, got, w)
		}
	}
}

func TestAddIntervalClampsToShortMonth(t *testing.T) {
	if got := AddInterval(time.Date(2026, 1, 31, 0, 0, 0, 0, time.UTC), store.Monthly); !got.Equal(time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Jan 31 + 1 month = %v", got)
	}
	if got := AddInterval(time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC), store.Monthly); !got.Equal(time.Date(2028, 3, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("Feb 29 2028 + 1 month = %v", got)
	}
}

func TestPeriodIndex(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 12, 0, 0, 0, time.UTC)
	for _, c := range []struct {
		at   time.Time
		want int
	}{
		{time.Date(2025, 12, 1, 0, 0, 0, 0, time.UTC), 0},
		{anchor, 0},
		{time.Date(2026, 2, 28, 12, 0, 0, 0, time.UTC), 1},
		{time.Date(2026, 2, 28, 12, 0, 0, 1, time.UTC), 2},
		{time.Date(2026, 3, 3, 0, 0, 0, 0, time.UTC), 2},
		{time.Date(2026, 3, 31, 12, 0, 0, 0, time.UTC), 2},
	} {
