func TestRenewalKeepsTheAnchorDayAfterAShortMonth(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, at := range []time.Time{time.Date(2026, 2, 28, 9, 30, 0, 0, time.UTC), time.Date(2026, 3, 31, 9, 30, 0, 0, time.UTC)} {
		e.Clock.Set(at)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue at %v = %d, %v", at, n, err)
		}
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 9, 30, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 9, 30, 0, 0, time.UTC)) {
		t.Fatalf("period = %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd)
	}
}

func TestLateRenewalCatchesUpEveryMissedPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The job did not run for two months and ran on May 1: periods starting Feb 28, Mar 31 and Apr 30 have started.
	e.Clock.Set(time.Date(2026, 5, 1, 4, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(time.Date(2026, 4, 30, 9, 30, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 5, 31, 9, 30, 0, 0, time.UTC)) {
		t.Fatalf("after catch-up = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 4 {
		t.Fatalf("invoices = %d, want one per period", len(invs))
	}
	for i, start := range []time.Time{
		time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC),
		time.Date(2026, 2, 28, 9, 30, 0, 0, time.UTC),
		time.Date(2026, 3, 31, 9, 30, 0, 0, time.UTC),
		time.Date(2026, 4, 30, 9, 30, 0, 0, time.UTC),
	} {
		if inv := invs[i]; inv.PeriodStart == nil || !inv.PeriodStart.Equal(start) || inv.Status != store.InvoicePaid {
			t.Fatalf("invoice %d = %+v, want paid for the period from %v", i, inv, start)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 4 {
		t.Fatalf("charges = %d, want 4", len(cs))
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed again: %d", n)
	}
}

func TestMeteredCatchUpBillsEachEndedPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, u := range []struct {
		q  int64
		at time.Time
	}{
		{100, time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC)},
		{7, time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)},
	} {
